import{_ as a,o as r,c as t,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"弗兰克·鲁尼","description":"","frontmatter":{"title":"弗兰克·鲁尼","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/弗兰克·鲁尼.md","filePath":"04_people/弗兰克·鲁尼.md"}'),l={name:"04_people/弗兰克·鲁尼.md"};function n(i,e,s,_,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="弗兰克·鲁尼-frank-rooney" tabindex="-1">弗兰克·鲁尼（Frank Rooney） <a class="header-anchor" href="#弗兰克·鲁尼-frank-rooney" aria-label="Permalink to &quot;弗兰克·鲁尼（Frank Rooney）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：H.H. Brown 制鞋公司 CEO</li><li><strong>与巴菲特关系</strong>：被巴菲特收购的制鞋公司 CEO</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>弗兰克·鲁尼是 H.H. Brown 制鞋公司的首席执行官。H.H. Brown 是一家历史悠久的美国制鞋企业，以生产高质量的工作靴和休闲鞋著称，在美国本土市场拥有广泛的分销网络和深厚的品牌积淀。公司以其经典的产品设计和可靠的品质在美国制鞋行业占据了稳固的地位。</p><p>巴菲特对制造业企业有着浓厚的兴趣，尤其偏爱那些具有持久竞争优势、品牌护城河和管理文化优秀的公司。H.H. Brown 正是这样一家企业——其产品在美国消费者中享有盛誉，多年积累的品牌价值构成了真正的竞争壁垒。巴菲特收购 H.H. Brown 后，继续由鲁尼担任 CEO，保持了公司管理层的稳定性和经营连续性。</p><p>鲁尼在 H.H. Brown 被伯克希尔收购后的过渡期中发挥了关键作用，确保了公司的企业文化、业务运营和产品质量在新的所有权框架下保持不变。在他的领导下，H.H. Brown 继续为伯克希尔贡献稳定的利润和现金流。巴菲特在股东信中多次提到 H.H. Brown 这类制鞋业务，将其视为伯克希尔制造业板块中可靠的业务单元，高度评价鲁尼的管理能力。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>收购前</strong>：作为 H.H. Brown CEO，带领公司在制鞋行业保持竞争力</li><li><strong>收购后</strong>：继续担任 CEO，推动公司平稳过渡至伯克希尔体系</li><li><strong>任期内</strong>：保持公司业务稳定，持续为伯克希尔贡献利润</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=弗兰克·鲁尼在2001年股东信中的原话">2001年：完整翻译|/01_letters/2001年/翻译</a></li><li><a href="/search?q=弗兰克·鲁尼在2010年股东信中的原话">2010年：完整翻译|/01_letters/2010年/翻译</a></li><li><a href="/search?q=弗兰克·鲁尼在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li><li><a href="/search?q=弗兰克·鲁尼在2002年股东信中的原话">2002年：完整翻译|/01_letters/2002年/翻译</a></li><li><a href="/search?q=弗兰克·鲁尼在1993年股东信中的原话">1993年：完整翻译|/01_letters/1993年/翻译</a></li></ul>',11)])])}const f=a(l,[["render",n]]);export{d as __pageData,f as default};
